#!/usr/bin/env node
/**
 * CLI entry point for onesource-docs-mcp.
 *
 * Usage:
 *   npx onesource-docs-mcp           # stdio mode (default)
 *   npx onesource-docs-mcp --http    # HTTP server on port 3001
 *   npx onesource-docs-mcp --http --port=8080
 *   npx onesource-docs-mcp --http --port 8080
 */
const args = process.argv.slice(2);
if (args.includes('--http')) {
    // Parse --port=N or --port N
    const portArgIdx = args.findIndex(a => a === '--port' || a.startsWith('--port='));
    if (portArgIdx !== -1) {
        const arg = args[portArgIdx];
        const portStr = arg.startsWith('--port=') ? arg.split('=')[1] : args[portArgIdx + 1];
        const port = parseInt(portStr || '', 10);
        if (!portStr || isNaN(port) || port < 1 || port > 65535) {
            console.error(`Error: Invalid port "${portStr ?? ''}". Must be a number between 1 and 65535.`);
            process.exit(1);
        }
        process.env.PORT = String(port);
    }
    // http-server.ts manages its own analytics lifecycle
    await import('./http-server.js');
}
else {
    const { createMcpServer, VERSION } = await import('./create-server.js');
    const { StdioServerTransport } = await import('@modelcontextprotocol/sdk/server/stdio.js');
    const { server, analytics } = createMcpServer({ transport: 'stdio' });
    const transport = new StdioServerTransport();
    await server.connect(transport);
    console.error('[onesource-docs] Server connected via stdio');
    analytics.trackService({
        type: 'service_start',
        service: 'onesource-docs',
        timestamp: new Date().toISOString(),
        version: VERSION,
        details: 'stdio cli',
    });
    process.once('SIGINT', async () => {
        console.error('[onesource-docs] Shutting down...');
        analytics.trackService({
            type: 'service_stop',
            service: 'onesource-docs',
            timestamp: new Date().toISOString(),
            version: VERSION,
        });
        analytics.stop();
        await analytics.flush();
        process.exit(0);
    });
}
export {};
